initialize_run_manifest <- function(config,mode) { id<-paste0(format(Sys.time(),"%Y%m%dT%H%M%SZ",tz="UTC"),"_",substr(digest::digest(list(config,mode),algo="xxhash32"),1,8)); d<-file.path(config$paths$run_dir,id); fs::dir_create(d,recurse=TRUE); list(run_id=id,run_dir=d,mode=mode,start_utc=as.character(Sys.time())) }
record_manifest_event <- function(manifest,...) { e<-data.frame(timestamp_utc=as.character(Sys.time()),event=as.character(list(...)[[1]]),stringsAsFactors=FALSE); f<-file.path(manifest$run_dir,"run_events.csv"); if(file.exists(f)) utils::write.table(e,f,sep=",",row.names=FALSE,col.names=FALSE,append=TRUE) else utils::write.csv(e,f,row.names=FALSE); manifest }
finalize_run_manifest <- function(manifest,status) { manifest$end_utc<-as.character(Sys.time()); manifest$status<-status; jsonlite::write_json(manifest,file.path(manifest$run_dir,"run_manifest.json"),pretty=TRUE,auto_unbox=TRUE); manifest }
